-- User-supplied mounting positions; preserve existing IDs and active states.
UPDATE mount_positions SET notes='Đầu kéo',version=version+1 WHERE code IN ('TT','TP') AND (notes IS NULL OR trim(notes)='');
UPDATE catalog_search SET normalized_text=normalized_text||' '||'đầu kéo' WHERE resource='mount-positions' AND field_key='all' AND entity_id IN (SELECT id FROM mount_positions WHERE code IN ('TT','TP') AND notes='Đầu kéo');
